function firstUniqChar(s) {
  // s[i] is unique when it does not occur before i and does not occur after i.
  for (let i = 0; i < s.length; i++) {
    if (s.indexOf(s[i]) === i && s.indexOf(s[i], i + 1) === -1) return i;
  }
  return -1;
}

