function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 10);
    const k = 1 + Math.floor(rand() * 5);
    let s = '';
    for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * k)];
    return [s];
  }
  const mode = Math.floor(rand() * 3);
  const n = 10000;
  if (mode === 0) {
    let s = '';
    for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * 26)];
    return [s];
  }
  // Every letter but the last one repeats, so a unique letter (or none) sits near the end.
  const k = 25;
  const chars = [];
  for (let i = 0; i < n - 1; i++) chars.push(letters[i % k]);
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  chars.push(mode === 1 ? 'z' : chars[0]);
  return [chars.join('')];
}
